from math import gcd


def countProductDivisible(nums, k):
    cnt = {}
    for x in nums:
        g = gcd(x, k)
        cnt[g] = cnt.get(g, 0) + 1
    items = list(cnt.items())
    ans = 0
    for i in range(len(items)):
        g1, c1 = items[i]
        if g1 * g1 % k == 0:
            ans += c1 * (c1 - 1) // 2
        for j in range(i + 1, len(items)):
            g2, c2 = items[j]
            if g1 * g2 % k == 0:
                ans += c1 * c2
    return ans
